// GENERATED — do not edit by hand.
//
// Every static page route in this project, derived from the App Router tree by
// the platform on each build (siteRoutesService). `sitemap.ts` lists these, so a
// page that exists is a page search engines are told about — listing routes by
// hand meant one forgotten line silently kept a page out of the sitemap, worst
// on a migrated site where the pages that most need re-indexing are brand new.
//
// It is a TS module rather than a JSON file read at runtime on purpose: the
// sitemap route can execute on the Cloudflare Worker, where `node:fs` is not
// available, so the list must be bundled at build time.
export const NOIMOS_ROUTES: string[] = ["/"];
